   783          }
   784          case SPNG_COLOR_TYPE_GRAYSCALE_ALPHA:
   785          {
   786              if( !(ihdr->bit_depth == 8 || ihdr->bit_depth == 16) )
   787                  return SPNG_EBIT_DEPTH;
   788
   789              break;
   790          }
   791          case SPNG_COLOR_TYPE_TRUECOLOR_ALPHA:
   792          {
   793              if( !(ihdr->bit_depth == 8 || ihdr->bit_depth == 16) )
   794                  return SPNG_EBIT_DEPTH;
